R=[]
def role(id,en,ru,positions,desc,descRu,keyAttrs,focuses):
    R.append(dict(id=id,nameEn=en,nameRu=ru,positions=positions,descEn=desc,descRu=descRu,keyAttrs=keyAttrs,focuses=focuses))
def fo(id,ru,descRu,tags,**v):
    base=dict(adv=0,inward=0,wide=0,att=0.3,def_=0.5,press=0.4,runs=0.2,create=0.3,box=0.1,roam=0.1,stam=0.5,stepOut=0,screen=0,sweep=0,hold=0,dropBack=0)
    base.update(v); base['def']=base.pop('def_'); base.pop('width',None)
    return dict(id=id,nameRu=ru,descRu=descRu,tags=tags,v=base)
