POSF={
 ('holding','CM'):['Defend','Ball-Winning'],('holding','CDM'):['Defend','Roaming','Ball-Winning'],
 ('deep_lying_playmaker','CM'):['Defend','Build-Up'],('deep_lying_playmaker','CDM'):['Defend','Roaming','Build-Up'],
 ('playmaker','CM'):['Attack','Roaming'],('playmaker','CAM'):['Balanced','Roaming','Build-Up'],
 ('half_winger','CM'):['Balanced','Attack','Support'],('half_winger','CAM'):['Balanced','Attack','Roaming'],
 ('winger','LM'):['Balanced','Attack'],('winger','RM'):['Balanced','Attack'],
 ('inside_forward','LM'):['Balanced','Attack'],('inside_forward','RM'):['Balanced','Attack'],
}
for r in R:
    r['focusByPosition']={}
    for p in r['positions']:
        allf=[f['id'] for f in r['focuses']]
        r['focusByPosition'][p]=POSF.get((r['id'],p),allf)
for r in R:
    if set(r['positions'])==set(FB): r['positions']=FB
